def prior_request_record(repo, did):
    cp = repo / ORIGINAL_OUTPUT / '_DAY1_CALL_CHECKPOINT.json'
    if not cp.exists():
        return 'UNKNOWN', 'No matching checkpoint available'
    try:
        d = json.loads(read_text(cp))
        item = d.get('items', {}).get(did, {})
        if item.get('status') == 'SAVED':
            return 'UNKNOWN', 'SAVED checkpoint but does not record VoiceId'
        return 'UNKNOWN', 'Checkpoint entry status ' + str(item.get('status', 'UNKNOWN'))
    except Exception:
        return 'UNKNOWN', 'Unreadable checkpoint'

def audio_response_to_wav(resp):
    try:
        part=next(p for p in resp.candidates[0].content.parts if p.inline_data is not None)
        dat=part.inline_data.data
        mime=str(part.inline_data.mime_type or '')
        raw=base64.b64decode(dat) if isinstance(dat,str) else bytes(dat)
    except Exception as e:
        raise RuntimeError('TTS 응답 오디오 추출 실패: '+type(e).__name__)
    if raw.startswith(b'RIFF'):
        return raw
    # Gemini raw PCM commonly 24000 Hz / 16-bit mono
    m=re.search(r'rate\s*=\s*(\d+)',mime)
    sr=int(m.group(1)) if m else 24000
    if sr!=24000:
        raise RuntimeError('비정상 raw sample rate='+str(sr))
    with io.BytesIO() as output:
        with wave.open(output,'wb') as w:
            w.setnchannels(1);w.setsampwidth(2);w.setframerate(sr);w.writeframes(raw)
        return output.getvalue()
